    if (index < 0) throw new DeskError('NOT_ENROLLED', 'Employee is not enrolled');
    const [removed] = session.enrollments.splice(index, 1);
    if (removed && removed.status !== 'waitlisted') {
      this.offerWaiting(session);
    }
  }

