  entry.email = 'changed@example.com';
  const roster = desk.roster('s');
  roster.enrollments[0].email = 'changed@example.com';
  roster.enrollments.length = 0;
  assert.equal(desk.roster('s').capacity, 1);
  assert.deepEqual(attendanceEmails(desk, 's'), ['a@example.com']);
});
test('configuration and domain errors', () => {
  assert.throws(() => new TrainingDesk([{ id: 's', title: 'x', capacity: 0 }]), { code: 'INVALID_SESSION' });
  const desk = make();
  assert.throws(() => desk.enroll('missing', 'bad'), { code: 'NOT_FOUND' });
  assert.throws(() => desk.enroll('s', 'bad'), { code: 'INVALID_EMAIL' });
  assert.deepEqual(desk.roster('s').enrollments, []);
});
import test from 'node:test';
import assert from 'node:assert/strict';
import { TrainingDesk } from '../dist/desk.js';
import { submitEnrollment, attendanceEmails } from '../dist/portal.js';

const make = () => new TrainingDesk([
  { id: 's', title: 'First aid', capacity: 1 },
  { id: 'other', title: 'Safety', capacity: 1 },
]);
const queue = desk => {
  for (const name of ['a', 'b', 'c', 'd']) {
    desk.enroll('s', `${name}@example.com`, { waitlist: true });
  }
  desk.cancel('s', 'a@example.com');
};

test('offers reserve seats, require acceptance for attendance, and preserve ownership', () => {
  const desk = make();
  queue(desk);
  const snapshot = desk.roster('s');
  assert.deepEqual(snapshot.enrollments, [
    { email: 'b@example.com', status: 'offered' },
    { email: 'c@example.com', status: 'waitlisted' },
    { email: 'd@example.com', status: 'waitlisted' },
  ]);
  assert.deepEqual(attendanceEmails(desk, 's'), []);
  assert.deepEqual(submitEnrollment(desk, { sessionId: 's', email: 'new@example.com' }), {
    ok: false, code: 'FULL',
  });
  assert.deepEqual(submitEnrollment(desk, { sessionId: 's', email: 'new@example.com', waitlist: true }), {
    ok: true, status: 'waitlisted',
  });
  assert.deepEqual(submitEnrollment(desk, { sessionId: 's', email: ' B@EXAMPLE.COM ' }), {
    ok: false, code: 'ALREADY_ENROLLED',
  });
  desk.setAdmissions('s', false);
  const accepted = desk.acceptOffer('s', ' B@EXAMPLE.COM ');
  assert.deepEqual(accepted, { email: 'b@example.com', status: 'confirmed' });
  assert.deepEqual(attendanceEmails(desk, 's'), ['b@example.com']);
  accepted.status = 'waitlisted';
  accepted.email = 'changed@example.com';
  snapshot.enrollments[0].email = 'changed@example.com';
  assert.equal(snapshot.enrollments[0].status, 'offered');
  assert.deepEqual(attendanceEmails(desk, 's'), ['b@example.com']);
  assert.equal(desk.roster('s').admissionsOpen, false);
  assert.equal(desk.enroll('other', 'b@example.com').status, 'confirmed');
});

test('declining and cancelling offered entries pass the reservation along FIFO only while open', () => {
  const desk = make();
  queue(desk);
  assert.equal(desk.declineOffer('s', ' B@EXAMPLE.COM '), undefined);
  assert.deepEqual(desk.roster('s').enrollments, [
    { email: 'c@example.com', status: 'offered' },
    { email: 'd@example.com', status: 'waitlisted' },
  ]);
  desk.cancel('s', ' C@EXAMPLE.COM ');
  assert.deepEqual(desk.roster('s').enrollments, [{ email: 'd@example.com', status: 'offered' }]);
  desk.enroll('s', 'e@example.com', { waitlist: true });
  desk.enroll('s', 'f@example.com', { waitlist: true });
  desk.setAdmissions('s', false);
  desk.declineOffer('s', 'd@example.com');
  assert.deepEqual(desk.roster('s').enrollments.map(entry => entry.status), ['waitlisted', 'waitlisted']);
  desk.setAdmissions('s', true);
  desk.setAdmissions('s', true);
  assert.deepEqual(desk.roster('s').enrollments.map(entry => entry.status), ['offered', 'waitlisted']);
  desk.setAdmissions('s', false);
  desk.cancel('s', 'e@example.com');
  assert.equal(desk.roster('s').enrollments[0].status, 'waitlisted');
  desk.setAdmissions('s', true);
  assert.equal(desk.roster('s').enrollments[0].status, 'offered');
  desk.acceptOffer('s', 'f@example.com');
  assert.deepEqual(attendanceEmails(desk, 's'), ['f@example.com']);
});

test('offer operations preserve error precedence and leave failures atomic in every status', () => {
  const desk = make();
  queue(desk);
  desk.enroll('other', 'confirmed@example.com');
  for (const open of [true, false]) {
    desk.setAdmissions('s', open);
    for (const method of ['acceptOffer', 'declineOffer']) {
      const before = desk.roster('s');
      assert.throws(() => desk[method]('missing', 'bad'), { code: 'NOT_FOUND' });
      assert.throws(() => desk[method]('s', 'bad'), { code: 'INVALID_EMAIL' });
      assert.throws(() => desk[method]('s', 'absent@example.com'), { code: 'NOT_ENROLLED' });
      assert.throws(() => desk[method]('s', ' C@EXAMPLE.COM '), { code: 'NOT_OFFERED' });
      assert.throws(() => desk[method]('other', 'confirmed@example.com'), { code: 'NOT_OFFERED' });
      assert.deepEqual(desk.roster('s'), before);
      assert.deepEqual(attendanceEmails(desk, 'other'), ['confirmed@example.com']);
    }
  }
  desk.acceptOffer('s', 'b@example.com');
  const before = desk.roster('s');
  assert.throws(() => desk.acceptOffer('s', 'b@example.com'), { code: 'NOT_OFFERED' });
  assert.throws(() => desk.declineOffer('s', 'b@example.com'), { code: 'NOT_OFFERED' });
  assert.deepEqual(desk.roster('s'), before);
});

test('reopening reserves every free seat once, keeps FIFO, and isolates sessions', () => {
  const desk = new TrainingDesk([
    { id: 's', title: 'First aid', capacity: 3 },
    { id: 'other', title: 'Safety', capacity: 1 },
  ]);
  for (const name of ['a', 'b', 'c', 'd', 'e', 'f', 'g']) {
    desk.enroll('s', `${name}@example.com`, { waitlist: true });
  }
  desk.setAdmissions('s', false);
  for (const name of ['a', 'b', 'c']) desk.cancel('s', `${name}@example.com`);
  desk.setAdmissions('s', true);
  const reopened = desk.roster('s');
  assert.deepEqual(reopened.enrollments.map(entry => entry.status), ['offered', 'offered', 'offered', 'waitlisted']);
  desk.acceptOffer('s', 'e@example.com');
  desk.setAdmissions('s', true);
  desk.setAdmissions('s', true);
  assert.deepEqual(desk.roster('s').enrollments.map(entry => entry.status), ['offered', 'confirmed', 'offered', 'waitlisted']);
  assert.deepEqual(attendanceEmails(desk, 's'), ['e@example.com']);
  desk.acceptOffer('s', 'd@example.com');
  assert.deepEqual(attendanceEmails(desk, 's'), ['d@example.com', 'e@example.com']);
  assert.equal(reopened.enrollments[0].status, 'offered');
  assert.throws(() => desk.enroll('s', 'new@example.com'), { code: 'FULL' });
  assert.equal(desk.enroll('other', 'g@example.com').status, 'confirmed');
});
import test from 'node:test';
import assert from 'node:assert/strict';
import { TrainingDesk } from '../dist/desk.js';
import { submitEnrollment, attendanceEmails } from '../dist/portal.js';

const make = () => new TrainingDesk([{ id: 's', title: 'First aid', capacity: 2 }]);

test('free seats confirm opt-ins; full sessions require explicit opt-in', () => {
  const desk = make();
  assert.equal(desk.enroll('s', 'a@example.com', { waitlist: true }).status, 'confirmed');
  assert.equal(desk.enroll('s', 'b@example.com', { waitlist: false }).status, 'confirmed');
  const before = desk.roster('s');
  for (const options of [undefined, { waitlist: false }]) {
    assert.throws(() => desk.enroll('s', 'c@example.com', options), { code: 'FULL' });
    assert.deepEqual(desk.roster('s'), before);
  }
  assert.deepEqual(desk.enroll('s', ' C@EXAMPLE.COM ', { waitlist: true }), {
    email: 'c@example.com', status: 'waitlisted',
  });
  assert.deepEqual(attendanceEmails(desk, 's'), ['a@example.com', 'b@example.com']);
  for (const email of [' A@EXAMPLE.COM ', ' C@EXAMPLE.COM ']) {
    for (const options of [undefined, { waitlist: true }]) {
      assert.throws(() => desk.enroll('s', email, options), { code: 'ALREADY_ENROLLED' });
    }
  }
  assert.equal(desk.roster('s').enrollments.length, 3);
});

test('cancellation removes waiting employees and offers seats to remaining employees in join order', () => {
  const desk = make();
  for (const name of ['a', 'b', 'c', 'd', 'e']) {
    desk.enroll('s', `${name}@example.com`, { waitlist: true });
  }
  desk.cancel('s', ' C@EXAMPLE.COM ');
  assert.deepEqual(attendanceEmails(desk, 's'), ['a@example.com', 'b@example.com']);
  desk.enroll('s', 'c@example.com', { waitlist: true });
  desk.cancel('s', ' A@EXAMPLE.COM ');
  assert.deepEqual(desk.roster('s').enrollments, [
    { email: 'b@example.com', status: 'confirmed' },
    { email: 'd@example.com', status: 'offered' },
    { email: 'e@example.com', status: 'waitlisted' },
    { email: 'c@example.com', status: 'waitlisted' },
  ]);
  assert.throws(() => desk.enroll('s', 'f@example.com'), { code: 'FULL' });
  desk.cancel('s', 'd@example.com');
  assert.deepEqual(attendanceEmails(desk, 's'), ['b@example.com']);
  desk.cancel('s', 'b@example.com');
  assert.deepEqual(attendanceEmails(desk, 's'), []);
  desk.cancel('s', 'e@example.com');
  assert.equal(desk.enroll('s', 'f@example.com').status, 'confirmed');
});

test('waitlist snapshots and desk instances retain independent ownership', () => {
  const desk = make();
  desk.enroll('s', 'a@example.com');
  desk.enroll('s', 'b@example.com');
  const entry = desk.enroll('s', 'c@example.com', { waitlist: true });
  const snapshot = desk.roster('s');
  entry.email = 'changed@example.com';
  entry.status = 'confirmed';
  snapshot.enrollments[2].status = 'confirmed';
  snapshot.enrollments.push({ email: 'extra@example.com', status: 'confirmed' });
  const attendance = attendanceEmails(desk, 's');
  attendance.length = 0;
  assert.deepEqual(desk.roster('s').enrollments[2], {
    email: 'c@example.com', status: 'waitlisted',
  });
  desk.cancel('s', 'a@example.com');
  assert.equal(snapshot.enrollments[0].email, 'a@example.com');
  assert.equal(entry.status, 'confirmed');
  assert.deepEqual(attendanceEmails(desk, 's'), ['b@example.com']);
  assert.equal(desk.roster('s').enrollments.find(entry => entry.email === 'c@example.com').status, 'offered');
  assert.deepEqual(make().roster('s').enrollments, []);
});

test('portal accepts boolean waitlist and returns the resulting enrollment status', () => {
  const desk = make();
  for (const [email, waitlist] of [['a@example.com', true], ['b@example.com', false]]) {
    assert.deepEqual(submitEnrollment(desk, { sessionId: 's', email, waitlist, extra: 1 }), {
      ok: true, status: 'confirmed',
    });
  }
  for (const extra of [{}, { waitlist: false }]) {
    assert.deepEqual(submitEnrollment(desk, { sessionId: 's', email: 'c@example.com', ...extra }), {
      ok: false, code: 'FULL',
    });
  }
  assert.deepEqual(submitEnrollment(desk, { sessionId: 's', email: ' C@EXAMPLE.COM ', waitlist: true }), {
    ok: true, status: 'waitlisted',
  });
  assert.deepEqual(submitEnrollment(desk, { sessionId: 's', email: 'c@example.com', waitlist: true }), {
    ok: false, code: 'ALREADY_ENROLLED',
  });
  assert.deepEqual(attendanceEmails(desk, 's'), ['a@example.com', 'b@example.com']);
  desk.cancel('s', 'a@example.com');
  assert.deepEqual(attendanceEmails(desk, 's'), ['b@example.com']);
  assert.equal(desk.roster('s').enrollments.find(entry => entry.email === 'c@example.com').status, 'offered');
});

test('portal rejects every nonboolean waitlist value before mutating or checking domain data', () => {
  const desk = make();
  for (const waitlist of [undefined, null, 0, 1, '', 'true', [], {}]) {
    for (const sessionId of ['s', 'missing']) {
      assert.deepEqual(submitEnrollment(desk, { sessionId, email: 'a@example.com', waitlist }), {
        ok: false, code: 'BAD_REQUEST',
      });
      assert.deepEqual(desk.roster('s').enrollments, []);
    }
  }
  assert.deepEqual(submitEnrollment(desk, { sessionId: 's', email: 'a@example.com' }), {
    ok: true, status: 'confirmed',
  });
});

test('waitlist preserves domain error precedence and failed-operation atomicity', () => {
  const desk = make();
  desk.enroll('s', 'a@example.com');
  desk.enroll('s', 'b@example.com');
  desk.enroll('s', 'c@example.com', { waitlist: true });
  const before = desk.roster('s');
  assert.throws(() => desk.enroll('missing', 'bad', { waitlist: true }), { code: 'NOT_FOUND' });
  assert.throws(() => desk.enroll('s', 'bad', { waitlist: true }), { code: 'INVALID_EMAIL' });
  assert.throws(() => desk.cancel('missing', 'bad'), { code: 'NOT_FOUND' });
  assert.throws(() => desk.cancel('s', 'bad'), { code: 'INVALID_EMAIL' });
  assert.throws(() => desk.cancel('s', 'absent@example.com'), { code: 'NOT_ENROLLED' });
  assert.deepEqual(desk.roster('s'), before);
  assert.deepEqual(submitEnrollment(desk, { sessionId: 'missing', email: 'bad', waitlist: true }), {
    ok: false, code: 'NOT_FOUND',
  });
  const programmingError = new Error('unexpected');
  assert.throws(() => submitEnrollment({ enroll() { throw programmingError; } }, {
    sessionId: 's', email: 'a@example.com', waitlist: true,
  }), error => error === programmingError);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { TrainingDesk } from '../dist/desk.js';
import { submitEnrollment, attendanceEmails } from '../dist/portal.js';

const make = (capacity = 2) => new TrainingDesk([
  { id: 's', title: 'First aid', capacity },
  { id: 'other', title: 'Safety', capacity: 1 },
]);
const enroll = (desk, name) => desk.enroll('s', `${name}@example.com`, { waitlist: true });

test('closed admissions reject all new requests before email and duplicate checks', () => {
  const desk = make();
  assert.equal(desk.roster('s').admissionsOpen, true);
  enroll(desk, 'a');
  desk.setAdmissions('s', false);
  desk.setAdmissions('s', false);
  const before = desk.roster('s');
  for (const email of ['bad', ' A@EXAMPLE.COM ', 'new@example.com']) {
    for (const options of [undefined, { waitlist: false }, { waitlist: true }]) {
      assert.throws(() => desk.enroll('s', email, options), { code: 'ADMISSIONS_CLOSED' });
      assert.deepEqual(submitEnrollment(desk, { sessionId: 's', email, ...options }),
        { ok: false, code: 'ADMISSIONS_CLOSED' });
    }
  }
  assert.deepEqual(submitEnrollment(desk, { sessionId: 's', email: 'a@example.com', waitlist: 'true' }),
    { ok: false, code: 'BAD_REQUEST' });
  assert.throws(() => desk.enroll('missing', 'bad'), { code: 'NOT_FOUND' });
  assert.throws(() => desk.setAdmissions('missing', false), { code: 'NOT_FOUND' });
  assert.deepEqual(desk.roster('s'), before);
  desk.setAdmissions('s', true);
  assert.throws(() => desk.enroll('s', 'bad'), { code: 'INVALID_EMAIL' });
  assert.throws(() => desk.enroll('s', 'a@example.com'), { code: 'ALREADY_ENROLLED' });
});

test('paused cancellations retain FIFO and reopening fills all vacancies before new arrivals', () => {
  const desk = make();
  for (const name of ['a', 'b', 'c', 'd', 'e', 'f']) enroll(desk, name);
  desk.setAdmissions('s', false);
  desk.cancel('s', ' A@EXAMPLE.COM ');
  desk.cancel('s', 'b@example.com');
  desk.cancel('s', 'd@example.com');
  assert.deepEqual(attendanceEmails(desk, 's'), []);
  assert.deepEqual(desk.roster('s').enrollments, ['c', 'e', 'f'].map(name => ({
    email: `${name}@example.com`, status: 'waitlisted',
  })));
  const paused = desk.roster('s');
  assert.throws(() => desk.cancel('s', 'missing@example.com'), { code: 'NOT_ENROLLED' });
  assert.throws(() => desk.cancel('s', 'bad'), { code: 'INVALID_EMAIL' });
  assert.deepEqual(desk.roster('s'), paused);
  desk.setAdmissions('s', true);
  assert.deepEqual(attendanceEmails(desk, 's'), []);
  assert.deepEqual(desk.roster('s').enrollments.map(entry => entry.status), ['offered', 'offered', 'waitlisted']);
  const reopened = desk.roster('s');
  desk.setAdmissions('s', true);
  assert.deepEqual(desk.roster('s'), reopened);
  assert.throws(() => desk.enroll('s', 'new@example.com'), { code: 'FULL' });
  assert.equal(enroll(desk, 'new').status, 'waitlisted');
  desk.cancel('s', 'c@example.com');
  assert.deepEqual(attendanceEmails(desk, 's'), []);
  assert.deepEqual(desk.roster('s').enrollments.map(entry => entry.status), ['offered', 'offered', 'waitlisted']);
  assert.equal(paused.admissionsOpen, false);
  assert.ok(paused.enrollments.every(entry => entry.status === 'waitlisted'));
});

test('reopening with fewer waiting employees leaves free seats and preserves isolation and ownership', () => {
  const desk = make();
  const independent = make();
  for (const name of ['a', 'b', 'c']) enroll(desk, name);
  desk.setAdmissions('s', false);
  const snapshot = desk.roster('s');
  snapshot.admissionsOpen = true;
  assert.equal(desk.roster('s').admissionsOpen, false);
  assert.equal(desk.roster('other').admissionsOpen, true);
  assert.equal(independent.roster('s').admissionsOpen, true);
  assert.equal(desk.enroll('other', 'a@example.com').status, 'confirmed');
  desk.cancel('s', 'a@example.com');
  desk.cancel('s', 'b@example.com');
  desk.setAdmissions('s', true);
  assert.deepEqual(attendanceEmails(desk, 's'), []);
  assert.equal(desk.roster('s').enrollments[0].status, 'offered');
  assert.equal(desk.enroll('s', 'd@example.com').status, 'confirmed');
  assert.deepEqual(attendanceEmails(desk, 'other'), ['a@example.com']);
});
